lab.solution:
END = None
root = {}

def add(word):
    if not word:
        raise ValueError('empty word is not stored')
    node = root
    for char in word:
        node = node.setdefault(char, {})
    node[END] = True

def walk(text):
    node = root
    for char in text:
        if char not in node:
            return None
        node = node[char]
    return node

def has_prefix(text):
    return walk(text) is not None

def contains(word):
    node = walk(word)
    return node is not None and END in node

add('cat')
add('car')
assert has_prefix('ca') and not contains('ca')
assert contains('cat') and contains('car') and not contains('cap')
print('prefix and word boundaries checked')
